$ErrorActionPreference = 'SilentlyContinue'
$d = Get-PSDrive C
"=== C DRIVE ==="
"Total GB : {0:N1}" -f (($d.Used + $d.Free)/1GB)
"Used  GB : {0:N1}" -f ($d.Used/1GB)
"Free  GB : {0:N1}" -f ($d.Free/1GB)

function SizeOf($p) {
  if (-not (Test-Path -LiteralPath $p)) { return $null }
  $sum = Get-ChildItem -LiteralPath $p -Recurse -File -Force -ErrorAction SilentlyContinue |
         Measure-Object -Property Length -Sum
  return [double]$sum.Sum
}

"=== TOP-LEVEL DIRS (C:\) ==="
Get-ChildItem C:\ -Directory -Force -ErrorAction SilentlyContinue | ForEach-Object {
  $s = SizeOf $_.FullName
  [pscustomobject]@{ Path=$_.FullName; GB=[math]::Round($s/1GB,2) }
} | Sort-Object GB -Descending | Format-Table -AutoSize | Out-String -Width 200

$ErrorActionPreference = 'SilentlyContinue'
function SizeOf($p) {
  if (-not (Test-Path -LiteralPath $p)) { return $null }
  $s = Get-ChildItem -LiteralPath $p -Recurse -File -Force -ErrorAction SilentlyContinue |
       Measure-Object -Property Length -Sum
  return [double]$s.Sum
}
function TopItems($root, $title, $n) {
  "=== $title ==="
  $rows = foreach ($i in Get-ChildItem -LiteralPath $root -Force -ErrorAction SilentlyContinue) {
    $s = if ($i.PSIsContainer) { SizeOf $i.FullName } else { $i.Length }
    [pscustomobject]@{ Name=$i.Name; GB=[math]::Round($s/1GB,2); MB=[math]::Round($s/1MB,0) }
  }
  $rows | Sort-Object GB -Descending | Select-Object -First $n | Format-Table -AutoSize | Out-String -Width 200
}
TopItems $env:TEMP "TEMP TOP 25" 25
TopItems "$env:USERPROFILE\Documents" "DOCUMENTS TOP 15" 15
TopItems "$env:USERPROFILE\.dsh" ".DSH TOP 15" 15
TopItems "$env:USERPROFILE\AppData\Local\npm-cache" "NPM-CACHE TOP 10" 10

$ErrorActionPreference = 'SilentlyContinue'
function Sum($p) {
  if (-not (Test-Path -LiteralPath $p)) { return 0 }
  $s = Get-ChildItem -LiteralPath $p -Recurse -File -Force -ErrorAction SilentlyContinue |
       Measure-Object -Property Length -Sum
  return [double]$s.Sum
}
$items = Get-ChildItem -LiteralPath $env:TEMP -Force -ErrorAction SilentlyContinue
"Temp child count: $($items.Count)"
$dwc = $items | Where-Object { $_.PSIsContainer -and $_.Name -like 'dsh-workspace-changes-*' }
"dsh-workspace-changes dirs: $($dwc.Count)"
$dwcSum = ($dwc | ForEach-Object { Sum $_.FullName } | Measure-Object -Sum).Sum
"dsh-workspace-changes total GB: {0:N2}" -f ($dwcSum/1GB)
"=== LARGEST INDIVIDUAL FILES IN TEMP (top 20) ==="
$files = Get-ChildItem -LiteralPath $env:TEMP -Recurse -File -Force -ErrorAction SilentlyContinue
$files | Sort-Object Length -Descending | Select-Object -First 20 |
  ForEach-Object { [pscustomobject]@{ MB=[math]::Round($_.Length/1MB,0); Path=$_.FullName } } |
  Format-Table -AutoSize | Out-String -Width 220
"=== TEMP SUBDIR TOTAL BY TOP PREFIX ==="
$groups = $items | Where-Object { $_.PSIsContainer } | Group-Object { ($_.Name -replace '-?[A-Za-z0-9]{6}$','') }
$groups | ForEach-Object {
  $g = ($_.Group | ForEach-Object { Sum $_.FullName } | Measure-Object -Sum).Sum
  [pscustomobject]@{ Group=$_.Name; Count=$_.Count; GB=[math]::Round($g/1GB,2) }
} | Sort-Object GB -Descending | Select-Object -First 20 | Format-Table -AutoSize | Out-String -Width 200
